-- Add Security+ SY0-801 as its own exam beside SY0-701.
-- Generated by scripts/sy0-801/build-migration.ts from src/data/sy0-801:
-- edit those and regenerate; don't edit this file.
--
-- It only adds rows. SY0-701 keeps its exam, questions, enrollments and
-- saved paths exactly as they are. SY0-801 gets a copy of each SY0-701
-- question that carries over, tagged to its SY0-801 objective and under the id
-- src/data/sy0-801/copies.json gives it, with SY0-801 wording where
-- src/data/sy0-801/map.ts gives one, plus its own new questions.

begin;

-- Stop before changing anything unless the database is the one this was built from.
do $$
declare
  src uuid := (select id from certifications where slug = 'security-plus-sy0-701');
begin
  if src is null then
    raise exception 'SY0-701 is missing';
  end if;
  if exists (select 1 from certifications where slug = 'security-plus-sy0-801') then
    raise exception 'SY0-801 already exists: this migration has already run';
  end if;
  if (select count(*) from cert_questions where certification_id = src and is_active) <> 842 then
    raise exception 'SY0-701: expected the 842-question bank this migration was built from';
  end if;
end $$;

-- The exam: the same format and passing score as SY0-701.
insert into certifications (slug, name, exam_code, vendor, total_exam_questions, passing_score, max_score, exam_duration_minutes)
values ('security-plus-sy0-801', 'CompTIA Security+', 'SY0-801', 'CompTIA', 90, 750, 900, 90);

-- Domains, weighted as CompTIA's SY0-801 exam objectives weight them.
insert into cert_domains (certification_id, domain_number, title, exam_weight, sort_order)
select c.id, v.domain_number, v.title, v.weight, v.sort_order
from (values
  ('1.0', 'General Security Concepts', 16, 1),
  ('2.0', 'Threats, Vulnerabilities, and Attacks', 24, 2),
  ('3.0', 'Security Architecture', 19, 3),
  ('4.0', 'Security Operations', 27, 4),
  ('5.0', 'Security Program Management and Oversight', 14, 5)
) as v(domain_number, title, weight, sort_order)
join certifications c on c.slug = 'security-plus-sy0-801';

-- Objectives, described in our own words: CompTIA's wording is copyrighted.
insert into cert_sub_objectives (domain_id, code, title, sort_order)
select d.id, v.code, v.title, v.sort_order
from (values
