  ('1.0', '1.2', 'How change management processes affect security', 2),
  ('1.0', '1.3', 'Cryptography in practice: PKI, certificates, encryption, hashing and signatures', 3),
  ('2.0', '2.1', 'What threats and vulnerabilities look like: intelligence, scoring and prioritizing', 1),
  ('2.0', '2.2', 'Threat actors, what drives them and what they can do', 2),
  ('2.0', '2.3', 'The vectors and sources attacks arrive through', 3),
  ('2.0', '2.4', 'Kinds of vulnerabilities and attack surfaces', 4),
  ('2.0', '2.5', 'Reading the signs of malicious activity', 5),
  ('2.0', '2.6', 'Threats and vulnerabilities that come with using AI', 6),
  ('3.0', '3.1', 'The security trade-offs of different architecture models', 1),
  ('3.0', '3.2', 'Managing security architecture to protect infrastructure', 2),
  ('3.0', '3.3', 'Protecting data: types, states, classifications, roles and handling', 3),
  ('3.0', '3.4', 'Resilience and recovery in security architecture', 4),
  ('4.0', '4.1', 'Mitigating controls and techniques that secure an environment', 1),
  ('4.0', '4.2', 'Security across the hardware, software and data asset life cycle', 2),
  ('4.0', '4.3', 'Running vulnerability management, from finding flaws to reporting', 3),
  ('4.0', '4.4', 'Security alerting and monitoring tools and concepts', 4),
  ('4.0', '4.5', 'Identity and access management in practice', 5),
  ('4.0', '4.6', 'Automation, orchestration and AI in security operations', 6),
  ('4.0', '4.7', 'What incident response involves, from preparation to lessons learned', 7),
  ('4.0', '4.8', 'Using data, artifacts and sources in a security investigation', 8),
  ('5.0', '5.1', 'Governance, risk and compliance documents and why they matter', 1),
  ('5.0', '5.2', 'Risk management processes and what they mean for security', 2),
  ('5.0', '5.3', 'Assessing and managing risk from third parties', 3),
  ('5.0', '5.4', 'What effective security compliance involves', 4),
  ('5.0', '5.5', 'Audits and assessments, their scope and methods', 5),
  ('5.0', '5.6', 'Security awareness that improves an organization''s security', 6)
) as v(domain_number, code, title, sort_order)
join certifications c on c.slug = 'security-plus-sy0-801'
